//! Selective staging uses patches generated by Git and applies only to the index.
use super::operations::{self, Operation};
use anyhow::{Context, Result, ensure};
use std::path::Path;

/// Return a patch containing only additions/deletions on the selected, zero-based
/// displayed diff lines. Unselected deletions become context; additions disappear.
/// Restrict this to ordinary text modifications so file modes, renames, binary
/// content and missing final newlines can never be silently changed.
pub fn selection_patch(diff: &[u8], range: (usize, usize)) -> Result<Vec<u8>> {
    let text = std::str::from_utf8(diff).context("Use whole-file staging for non-UTF-8 content")?;
    ensure!(
        text.matches("diff --git ").count() == 1 && text.lines().any(|l| l.starts_with("index ")),
        "Choose a regular modified text file"
    );
    ensure!(
        !text.contains("\nnew file mode ")
            && !text.contains("\ndeleted file mode ")
            && !text.contains("\nold mode ")
            && !text.contains("\nGIT binary patch")
            && !text.contains("\nBinary files ")
            && !text.contains("\n\\ No newline"),
        "Use whole-file staging for new, deleted, binary, mode-changing or unterminated files"
    );
    let lines: Vec<_> = text.split_inclusive('\n').collect();
    let first = lines.iter().position(|l| l.starts_with("@@ ")).context("No text hunks to stage")?;
    let mut patch = lines[..first].concat();
    let mut i = first;
    let mut delta = 0isize;
    let mut chosen = 0;
    while i < lines.len() {
        let header = lines[i];
        ensure!(header.starts_with("@@ -"), "Unexpected diff header");
        let old = header.split_whitespace().nth(1).context("Invalid hunk")?.trim_start_matches('-');
        let old_start: isize = old.split(',').next().unwrap().parse()?;
        i += 1;
        let mut body = String::new();
        let mut old_count = 0;
        let mut new_count = 0;
        let mut changed = false;
        while i < lines.len() && !lines[i].starts_with("@@ ") {
            let line = lines[i];
            let selected = i >= range.0 && i < range.1;
            match line.as_bytes().first() {
                Some(b' ') => {
                    body.push_str(line);
                    old_count += 1;
                    new_count += 1;
                }
                Some(b'-') => {
                    old_count += 1;
                    if selected {
                        body.push_str(line);
                        changed = true;
                    } else {
                        body.push(' ');
                        body.push_str(&line[1..]);
                        new_count += 1;
                    }
                }
                Some(b'+') => {
                    if selected {
                        body.push_str(line);
                        new_count += 1;
                        changed = true;
                    }
                }
                _ => anyhow::bail!("Unsupported diff line; use whole-file staging"),
            }
            i += 1;
        }
        if changed {
            let new_start = old_start
                + delta
                + if old_count == 0 {
                    1
                } else if new_count == 0 {
                    -1
                } else {
                    0
                };
            patch.push_str(&format!("@@ -{old_start},{old_count} +{new_start},{new_count} @@\n"));
            patch.push_str(&body);
            delta += new_count as isize - old_count as isize;
            chosen += 1;
        }
    }
    ensure!(chosen > 0, "Select added or removed lines, or place the cursor inside a hunk");
    Ok(patch.into_bytes())
}
pub fn hunk_range(diff: &[u8], cursor: usize) -> Result<(usize, usize)> {
    let text = std::str::from_utf8(diff)?;
    let lines: Vec<_> = text.lines().collect();
    ensure!(!lines.is_empty(), "Place the cursor in a diff hunk");
    let start = (0..=cursor.min(lines.len().saturating_sub(1)))
        .rev()
        .find(|i| lines[*i].starts_with("@@ "))
        .context("Place the cursor in a diff hunk")?;
    let end = (start + 1..lines.len())
        .find(|i| lines[*i].starts_with("@@ ") || lines[*i].starts_with("diff --git "))
        .unwrap_or(lines.len());
    Ok((start, end))
}
pub fn stage_selection(root: &Path, file: &Path, expected: &[u8], range: (usize, usize)) -> Result<Vec<u8>> {
    let current = operations::run(root, Operation::Diff { file: file.into(), cached: false, untracked: false })?;
    ensure!(current == expected, "The file or index changed since this diff was loaded. Refresh and select the changes again.");
    let patch = selection_patch(expected, range)?;
    operations::run(root, Operation::CheckPatch(patch.clone()))?;
    operations::run(root, Operation::ApplyPatch(patch))
}
